import java.util.*;
import java.io.*;

public class DStress2_Variant3 {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int length = scanner.nextInt();
        String inputStr = scanner.next();
        System.out.println(new DStress2_Variant3().computeCost(inputStr.toCharArray()));
        scanner.close();
    }

    int INF = Integer.MAX_VALUE / 3;

    int computeCost(char[] sequence) {
        List<Integer> vPositions = new ArrayList<>();
        List<Integer> kPositions = new ArrayList<>();
        List<Integer> otherPositions = new ArrayList<>();
        for (int i = 0; i < sequence.length; i++) {
            if (sequence[i] == 'V') vPositions.add(i);
            else if (sequence[i] == 'K') kPositions.add(i);
            else otherPositions.add(i);
        }
        int[][][][] dpTable = new int[2][vPositions.size() + 1][kPositions.size() + 1][otherPositions.size() + 1];
        for (int[][][] layer : dpTable)
            for (int[][] row : layer)
                for (int[] col : row)
                    Arrays.fill(col, INF);
        dpTable[0][0][0][0] = 0;
        for (int vCount = 0; vCount <= vPositions.size(); vCount++) {
            for (int kCount = 0; kCount <= kPositions.size(); kCount++) {
                for (int oCount = 0; oCount <= otherPositions.size(); oCount++) {
                    for (int lastFlag = 0; lastFlag < 2; lastFlag++) {
                        int currentCost = dpTable[lastFlag][vCount][kCount][oCount];
                        if (currentCost == INF) continue;
                        if (vCount < vPositions.size()) {
                            int newCost = currentCost + count(vPositions.get(vCount), kCount, kPositions) + count(vPositions.get(vCount), oCount, otherPositions);
                            dpTable[1][vCount + 1][kCount][oCount] = Math.min(dpTable[1][vCount + 1][kCount][oCount], newCost);
                        }
                        if (kCount < kPositions.size() && lastFlag == 0) {
                            int newCost = currentCost + count(kPositions.get(kCount), vCount, vPositions) + count(kPositions.get(kCount), oCount, otherPositions);
                            dpTable[0][vCount][kCount + 1][oCount] = Math.min(dpTable[0][vCount][kCount + 1][oCount], newCost);
                        }
                        if (oCount < otherPositions.size()) {
                            int newCost = currentCost + count(otherPositions.get(oCount), vCount, vPositions) + count(otherPositions.get(oCount), kCount, kPositions);
                            dpTable[0][vCount][kCount][oCount + 1] = Math.min(dpTable[0][vCount][kCount][oCount + 1], newCost);
                        }
                    }
                }
            }
        }
        return Math.min(dpTable[0][vPositions.size()][kPositions.size()][otherPositions.size()], dpTable[1][vPositions.size()][kPositions.size()][otherPositions.size()]);
    }

    private int count(int position, int startIdx, List<Integer> list) {
        int cnt = 0;
        for (int i = startIdx; i < list.size(); i++) {
            if (list.get(i) < position) cnt++;
        }
        return cnt;
    }
}
