import sys

def main():
    input_data = sys.stdin.read().strip().split()
    length = int(input_data[0])
    inputStr = input_data[1]
    print(computeCost(list(inputStr)))

INF = float('inf') / 3

def computeCost(sequence):
    vPositions = []
    kPositions = []
    otherPositions = []

    for i, ch in enumerate(sequence):
        if ch == 'V':
            vPositions.append(i)
        elif ch == 'K':
            kPositions.append(i)
        else:
            otherPositions.append(i)

    vSize = len(vPositions)
    kSize = len(kPositions)
    oSize = len(otherPositions)

    # Initialize 4D DP array
    dpTable = [[[[INF for _ in range(oSize + 1)] for _ in range(kSize + 1)] for _ in range(vSize + 1)] for _ in range(2)]
    dpTable[0][0][0][0] = 0

    for vCount in range(vSize + 1):
        for kCount in range(kSize + 1):
            for oCount in range(oSize + 1):
                for lastFlag in range(2):
                    currentCost = dpTable[lastFlag][vCount][kCount][oCount]
                    if currentCost == INF:
                        continue
                    # Add 'V'
                    if vCount < vSize:
                        newCost = currentCost + count(vPositions[vCount], kCount, kPositions) + count(vPositions[vCount], oCount, otherPositions)
                        if newCost < dpTable[1][vCount + 1][kCount][oCount]:
                            dpTable[1][vCount + 1][kCount][oCount] = newCost
                    # Add 'K'
                    if kCount < kSize and lastFlag == 0:
                        newCost = currentCost + count(kPositions[kCount], vCount, vPositions) + count(kPositions[kCount], oCount, otherPositions)
                        if newCost < dpTable[0][vCount][kCount + 1][oCount]:
                            dpTable[0][vCount][kCount + 1][oCount] = newCost
                    # Add other
                    if oCount < oSize:
                        newCost = currentCost + count(otherPositions[oCount], vCount, vPositions) + count(otherPositions[oCount], kCount, kPositions)
                        if newCost < dpTable[0][vCount][kCount][oCount + 1]:
                            dpTable[0][vCount][kCount][oCount + 1] = newCost

    return min(dpTable[0][vSize][kSize][oSize], dpTable[1][vSize][kSize][oSize])

def count(position, startIdx, lst):
    cnt = 0
    for i in range(startIdx, len(lst)):
        if lst[i] < position:
            cnt += 1
    return cnt

if __name__ == "__main__":
    main()

